from django.core.exceptions import ValidationError

from bloomerp.models.document_signing import (
    SignatureFieldType,
    SignatureLayoutField,
    SignatureLayoutRole,
)
from bloomerp.models.document_signing.signature_layout import SignatureLayout
from bloomerp.models.document_templates.document_template import DocumentTemplate
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .support import SigningFixturesMixin


class TestSignatureLayoutModel(SigningFixturesMixin, BloomerpModelTestCase):
    """Cover independent layouts, preview files, and optional template defaults."""

    model = SignatureLayout

    def attach_default(self, layout: SignatureLayout) -> None:
        """Associate an existing document template with an otherwise generic layout."""
        self.template = DocumentTemplate.objects.create(
            name="Agreement", default_signature_layout=layout
        )

    def validate_default_removed(self, layout: SignatureLayout) -> bool:
        """Keep a document template usable when its default layout is removed."""
        self.template.refresh_from_db()
        return self.template.default_signature_layout_id is None

    def attach_placements(self, layout: SignatureLayout) -> None:
        """Populate an unused layout so its complete aggregate can be removed."""
        role = SignatureLayoutRole.objects.create(
            layout=layout, key="party", label="Party"
        )
        SignatureLayoutField.objects.create(
            layout=layout,
            role=role,
            key="signature",
            field_type=SignatureFieldType.SIGNATURE,
        )

    def validate_placements_removed(self, layout: SignatureLayout) -> bool:
        """Ensure layout deletion removes its own roles and placements together."""
        return not SignatureLayoutRole.objects.filter(layout_id=layout.pk).exists()

    def get_test_scenarios(self) -> list[ModelScenario[SignatureLayout]]:
        """Exercise standalone configuration and safe optional preview references."""
        return [
            ModelScenario(
                name="Delete an unused layout together with its roles and placements",
                create_args={"name": "Unused layout"},
                post_create=self.attach_placements,
                delete_validators=self.validate_placements_removed,
            ),
            ModelScenario(
                name="Create and revise a layout without a document template",
                create_args={"name": "Generic layout"},
                update_args={"revision": 2},
            ),
            ModelScenario(
                name="Use an immutable file as a layout preview",
                create_args=partial(self.preview_args, folder=False),
            ),
            ModelScenario(
                name="Reject folders as preview documents",
                create_args=partial(self.preview_args, folder=True),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject a zero layout revision",
                create_args={"name": "Invalid revision", "revision": 0},
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Deleting a default layout preserves its document template",
                create_args={"name": "Optional default"},
                post_create=self.attach_default,
                delete_validators=self.validate_default_removed,
            ),
        ]

    def preview_args(self, folder: bool) -> dict[str, object]:
        """Choose either a valid file preview or an invalid folder reference."""
        return {
            "name": "Preview layout",
            "preview_file": self.folder if folder else self.original,
        }
